// DecodeDisconnectRequest returns a decoder for requests sent to the
// slackDirectoryConnections disconnect endpoint.
func DecodeDisconnectRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*slackdirectoryconnections.DisconnectPayload, error) {
	return func(r *http.Request) (*slackdirectoryconnections.DisconnectPayload, error) {
		var payload *slackdirectoryconnections.DisconnectPayload
		var (
			body DisconnectRequestBody
			err  error
		)
		err = decoder(r).Decode(&body)
		if err != nil {
			if errors.Is(err, io.EOF) {
				return payload, goa.MissingPayloadError()
			}
			var gerr *goa.ServiceError
			if errors.As(err, &gerr) {
				return payload, gerr
			}
			return payload, goa.DecodePayloadError(err.Error())
		}
		err = ValidateDisconnectRequestBody(&body)
		if err != nil {
			return payload, err
		}

		var (
			sessionToken *string
		)
		sessionTokenRaw := r.Header.Get("Gram-Session")
		if sessionTokenRaw != "" {
			sessionToken = &sessionTokenRaw
		}
		payload = NewDisconnectPayload(&body, sessionToken)
		if payload.SessionToken != nil {
			if strings.Contains(*payload.SessionToken, " ") {
				// Remove authorization scheme prefix (e.g. "Bearer")
				cred := strings.SplitN(*payload.SessionToken, " ", 2)[1]
				payload.SessionToken = &cred
			}
		}

		return payload, nil
	}
}

